import base64, hashlib, json, os

PASSWORD = 'GoSanchari@2026'


def pw(password: str) -> str:
    salt = os.urandom(16)
    h = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100_000, 32)
    return f"pbkdf2$100000${base64.b64encode(salt).decode()}${base64.b64encode(h).decode()}"


def q(v):
    if v is None:
        return 'NULL'
    if isinstance(v, bool):
        return '1' if v else '0'
    if isinstance(v, (int, float)):
        return str(v)
    if isinstance(v, (list, dict)):
        v = json.dumps(v, ensure_ascii=False)
    return "'" + str(v).replace("'", "''") + "'"


def d(days: int) -> str:
    return f"date('now', '+5 hours', '+30 minutes', '{days:+d} days')"


def ts(days: float) -> str:
    return f"strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '{days * 24:+.1f} hours')"


