# Bookings: one upcoming (tomorrow check-in), one completed with payment, one in stay.
def booking(bid, code, uid, pid, rid, ci, co, nights, adults, children, subtotal, total, taxes, status, pstatus, paid, name, phone, staff, created):
    out.append(
        'INSERT INTO bookings (id, code, user_id, property_id, room_id, check_in, check_out, nights, adults, children, rooms_count, subtotal, taxes, total, amount_paid, status, payment_status, source, guest_name, guest_phone, staff_id, created_at) VALUES ('
        + ', '.join([q(bid), q(code), q(uid), q(pid), q(rid), d(ci), d(co), q(nights), q(adults), q(children), '1', q(subtotal), q(taxes), q(total), q(paid), q(status), q(pstatus), q('website' if staff is None else 'quotation'), q(name), q(phone), q(staff), ts(created)])
        + ');')
    if paid:
        out.append(f"INSERT INTO payments (booking_id, amount, status, gateway, gateway_order_id, gateway_payment_id, created_at, updated_at) VALUES ({bid}, {paid}, 'paid', 'simulator', 'sim_order_seed_{bid}', 'sim_pay_seed_{bid}', {ts(created)}, {ts(created)});")

booking(1, 'GS-BK-DEMO01', 13, 8, room_ids[8][0], 1, 3, 2, 2, 0, 10400, 10920, 520, 'confirmed', 'paid', 10920, 'David Thomas', '+919812345604', None, -10)
booking(2, 'GS-BK-DEMO02', 14, 3, room_ids[3][0], -6, -3, 3, 2, 1, 8400, 8820, 420, 'completed', 'paid', 8820, 'Lakshmi Iyer', '+919812345605', 4, -25)
booking(3, 'GS-BK-DEMO03', 11, 7, room_ids[7][0], -1, 2, 3, 2, 0, 16500, 17325, 825, 'checked_in', 'paid', 17325, 'Sneha Pillai', '+919812345602', 3, -15)
out.append("INSERT INTO payouts (property_id, booking_id, amount, status) VALUES (3, 2, 7140, 'pending'), (7, 3, 13530, 'pending');")

out.append("INSERT INTO activity_log (user_id, action, entity, entity_id, details) VALUES (1, 'seed.loaded', 'system', NULL, '{\"note\":\"Demo data loaded\"}');")
out.append('PRAGMA foreign_keys = ON;')

path = os.path.join(os.path.dirname(__file__), 'seed.sql')
with open(path, 'w') as f:
    f.write('\n'.join(out) + '\n')
print(f'Wrote {path} ({len(out)} statements). Demo staff password: {PASSWORD}')
